style.css:
/* Nome do Tema: Angel's */
/* Descrição: Um Tema Sordito */

/* Aplica o estilo ao corpo da página (body) */
body {
    /* Define a imagem de fundo */
    background-image: url("https://pbs.twimg.com/media/Gg8YvDxXsAAMgB5.jpg");
    /* Ajusta o posicionamento e tamanho da imagem */
    background-position: center center;
    background-size: cover;
    background-repeat: no-repeat;
    /* Define a cor de fundo para caso a imagem não carregue */
    background-color: #222; /* Um tom de cinza escuro */
    /* Define a cor do texto */
    color: #eee; /* Um tom de cinza claro */
}

/* Opcional: Personalize outros elementos da página */
/* Por exemplo, para mudar a cor dos links: */
a {
    color: #88c0d0; /* Um tom de azul claro */
}
a:hover {
    color: #a3be8c; /* Um tom de verde claro quando o mouse passa por cima */
}

/* Outros exemplos de personalização: */
/* Para mudar a cor do cabeçalho (h1): */
h1 {
    color: #d08770; /* Um tom de vermelho claro */
}
/* Para mudar a cor do texto do parágrafo (p) */
p{
   color: #E0E0E0;
}

/* Para remover barras de rolagem */
::-webkit-scrollbar {
    display: none;
}

/* Para tornar o texto mais legível em fundos escuros */
body {
   text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5); /* Adiciona sombra ao texto */
}
